from pathlib import Path
p=Path(__file__).resolve().parents[1];f=p/'04_研发源码/app/r4/xuanliu.js';s=f.read_text(encoding='utf-8')
s=s.replace("xlScene.host.removeEventListener('pointerleave',xlScene.leave);", "xlScene.host.removeEventListener('pointerleave',xlScene.leave);xlScene.host.removeEventListener('pointerdown',xlScene.press);")
s=s.replace("visible:true,width:0,height:0", "visible:true,width:0,height:0,started:performance.now(),energy:0,ripples:[],frames:0")
a=s.index(' function draw(');b=s.index(' function tick(',a)
new=r''' function draw(time=0){if(xlScene!==scene||!host.isConnected)return;scene.frame=0;if(document.hidden||!scene.visible)return;const w=host.clientWidth,h=host.clientHeight,dpr=Math.min(devicePixelRatio||1,1.75);if(!w||!h)return;if(w!==scene.width||h!==scene.height){scene.width=w;scene.height=h;canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);}ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);scene.frames++;const night=isNight(),rgb=night?'235,186,110':'126,91,41',t0=media.matches?2.3:Math.max(0,time-scene.started)/1000,practice=state.page==='player',pace=practice?.55:1,pulse=practice&&state.audioPlaying&&!media.matches?1+Math.sin(t0*Math.PI/4)*.09:1,center=h*.66,ox=scene.x*33,oy=scene.y*13,flow=t0*pace,force=media.matches?0:scene.energy;scene.energy*=.91;
 function point(x,depth,row){const drift=media.matches?0:Math.sin(flow*.75+depth*2)*w*.025,peak=(Math.exp(-Math.pow((x-w*.32-ox-drift)/(w*.19),2))*h*.24+Math.exp(-Math.pow((x-w*.81+ox+drift)/(w*.15),2))*h*.32)*(1-depth*.65),ripple=Math.sin(x*.033+row*.17+flow*2.1)*6.5+Math.sin(x*.059-row*.12-flow*.9)*3.2,local=force*Math.exp(-Math.pow((x-w*(scene.x+.5))/(w*.25),2))*Math.sin(x*.047-flow*6)*h*.065;return center-h*.14+depth*h*.46-peak*pulse+ripple+oy+local;}
 for(let row=0;row<40;row++){const depth=row/40;ctx.beginPath();for(let i=0;i<=88;i++){const x=i/88*w,y=point(x,depth,row);i?ctx.lineTo(x,y):ctx.moveTo(x,y);}ctx.strokeStyle=`rgba(${rgb},${(night?.18:.1)+(1-depth)*(night?.31:.24)})`;ctx.lineWidth=row%5===0?1:.55;ctx.stroke();}
 // Travelling highlights move through the terrain, rather than blinking the whole panel.
 ctx.save();ctx.beginPath();ctx.rect(0,h*.37,w,h*.63);ctx.clip();for(let band=0;band<3;band++){const row=8+band*10,depth=row/40,head=((flow*.22+band*.36)%1.45)*w-w*.2,tail=head-w*.29,gradient=ctx.createLinearGradient(tail,0,head,0);gradient.addColorStop(0,`rgba(${rgb},0)`);gradient.addColorStop(.55,`rgba(${rgb},${night?.58:.34})`);gradient.addColorStop(1,`rgba(${night?'255,224,165':rgb},${night?.96:.7})`);ctx.beginPath();for(let i=0;i<=35;i++){const x=tail+(head-tail)*i/35,y=point(x,depth,row);i?ctx.lineTo(x,y):ctx.moveTo(x,y);}ctx.strokeStyle=gradient;ctx.lineWidth=night?1.8:1.4;ctx.shadowColor=`rgba(${rgb},.55)`;ctx.shadowBlur=night?9:3;ctx.stroke();ctx.shadowBlur=0;}
 for(let i=0;i<14;i++){const row=(i*7)%38,depth=row/40,x=((flow*(.14+(i%3)*.025)+i*.137)%1.25)*w-w*.1,y=point(x,depth,row);ctx.fillStyle=`rgba(${rgb},${night?.8:.55})`;ctx.beginPath();ctx.arc(x,y,i%4===0?1.6:.9,0,Math.PI*2);ctx.fill();}
 if(!media.matches){scene.ripples=scene.ripples.filter(r=>time-r.at<1000);for(const r of scene.ripples){const age=(time-r.at)/1000,ease=1-Math.pow(1-age,3),radius=8+ease*w*.6;ctx.beginPath();ctx.ellipse(r.x,r.y,radius,radius*.4,0,0,Math.PI*2);ctx.strokeStyle=`rgba(${rgb},${(1-age)*.7})`;ctx.lineWidth=1.2;ctx.stroke();}}
 ctx.restore();if(!media.matches)scene.frame=requestAnimationFrame(tick);}
'''
s=s[:a]+new+s[b:];s=s.replace('t0-scene.last<50','t0-scene.last<32')
s=s.replace("scene.y=(e.clientY-r.top)/r.height-.5;requestDraw();", "scene.y=(e.clientY-r.top)/r.height-.5;if(!media.matches)scene.energy=1;requestDraw();")
s=s.replace("scene.leave=()=>", "scene.press=e=>{if(media.matches)return;const r=host.getBoundingClientRect();scene.x=(e.clientX-r.left)/r.width-.5;scene.y=(e.clientY-r.top)/r.height-.5;scene.energy=1.6;scene.ripples.push({x:e.clientX-r.left,y:Math.max(r.height*.42,e.clientY-r.top),at:performance.now()});scene.ripples=scene.ripples.slice(-3);requestDraw();};scene.leave=()=>")
s=s.replace("scene.motion=()=>{cancelAnimationFrame(scene.frame);", "scene.motion=()=>{scene.ripples=[];scene.energy=0;cancelAnimationFrame(scene.frame);")
s=s.replace("host.addEventListener('pointerleave',scene.leave,{passive:true});", "host.addEventListener('pointerleave',scene.leave,{passive:true});host.addEventListener('pointerdown',scene.press,{passive:true});")
f.write_text(s,encoding='utf-8');print('Updated visible terrain flow, travelling light, pointer energy and touch ripple. Motion remains bounded and accessible.')
